module tb_TopModule;
    logic [7:0] in;
    logic [7:0] out;

    TopModule dut (
        .in(in),
        .out(out)
    );

    initial begin
        integer i;
        logic [7:0] expected;

        for (i = 0; i < 256; i = i + 1) begin
            in = i[7:0];
            #1;
            // compute expected: reverse bits of i
            expected = {i[0], i[1], i[2], i[3], i[4], i[5], i[6], i[7]};
            if (out !== expected) begin
                $display("SELFTEST FAIL: in=%0b, out=%0b, expected=%0b", in, out, expected);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
